const L = require('lv-automation').w10;
const j = $json; const op = L.classifyOp(j);
const sp = L.parseSlotPayload((j.msg && (j.msg.payload || j.msg.list_id)) || '');
const cr = L.parseCancelReason((j.msg && (j.msg.payload || j.msg.list_id)) || '');
return { json: { ...j, op, pick: sp, cancel_reason: L.cancelReasonOf(j), booking_id: (sp && sp.booking_id) || (cr && cr.booking_id) || (j.booking && j.booking.id) || null, lead_id: j.lead ? j.lead.id : null } };

const i = $('Classify op').item.json; const r = $json;
const __o = { ...i, bk: { id: r.id, client_id: r.client_id, broker_id: r.broker_id, brand_id: r.brand_id, appointment_date: r.appointment_date, ends_at: r.ends_at, method: r.method, status: r.status, graph_event_id: r.graph_event_id, calendar_provider: r.calendar_provider, reschedule_count: r.reschedule_count, booked_at: r.booked_at, verify_by: r.verify_by, guest_email: r.guest_email || null }, ld: { id: r.client_id, first_name: r.first_name, last_name: r.last_name, phone: r.phone, email: r.email, email_status: r.email_status, email_verified: r.email_verified === true, conv_state: r.conv_state || {}, opted_out_at: r.opted_out_at, language: r.language, stage: r.stage }, br: { id: r.broker_id, contact_person: r.contact_person, fsp_number: r.fsp_number || null, practice_name: r.practice_name || null, firm_name: r.firm_name || null, whatsapp_number: r.whatsapp_number, email: r.broker_email, methods_supported: r.methods_supported, calendar_email: r.calendar_email, calendar_status: r.calendar_status, calendar_mode: r.calendar_mode, calendar_status_detail: r.calendar_status_detail, buffer_minutes: r.buffer_minutes || 15, slot_minutes: r.slot_minutes || 30, last_inbound_ms: r.broker_last_inbound_at ? Date.parse(r.broker_last_inbound_at) : NaN }, brand: { booking_ui: r.booking_ui || $env.BOOKING_UI_DEFAULT || 'list', booking_flow_id: r.booking_flow_id, code: r.brand_code || null, start_page: r.brand_start_page === 'on' }, last_inbound_ms: r.last_inbound_at ? Date.parse(r.last_inbound_at) : NaN };
// cancel card (patch-w10-cancel-card.mjs): a typed "Another reason" counts only for its booking inside the 30-min wait
const W = require('lv-automation').w10;
if (__o.cancel_reason && __o.cancel_reason.typed && !W.typedReasonValid(__o.ld, __o.bk, Date.now())) __o.op = 'cancel_reason_stale';
__o.delegate = W.reasonDelegate(__o.op === 'cancel' ? __o.cancel_reason : null, __o.ld, __o.bk, __o.delegate || null);
__o.reason_params = W.reasonParams(__o.source === 'W12' ? null : __o.cancel_reason); // [code, typed text] for the SQL
__o.cancel_wait = __o.op === 'cancel_other' ? JSON.stringify(W.cancelReasonPending(__o.bk, Date.now())) : '';
return { json: __o };

const L = require('lv-automation').w10;
const j = $('Merge context').item.json;
// start-page brand, out of the 24-h window: the reschedule_card template needs the lead token (minted as W07's card does)
let token = null;
if (j.brand && j.brand.start_page === true && j.ld && j.ld.id) { try { token = require('lv-automation').leadToken.mintLeadToken(j.ld.id, { secret: $env.LEAD_TOKEN_SECRET }).token; } catch (e) { token = null; } }
const card = { start_page: !!(j.brand && j.brand.start_page === true), token, env: { WHATSAPP_PROVIDER: $env.WHATSAPP_PROVIDER, TWILIO_CONTENT_SIDS: $env.TWILIO_CONTENT_SIDS } };
const o = L.offerMessage({ booking: j.bk, lead: j.ld, broker: j.br, brand: j.brand, slots: $json.slots || [], now_ms: Date.now(), last_inbound_ms: j.last_inbound_ms, reason: j.op, delegate: j.delegate || null, card }); // I-39a: delegate.body is the one message body
let wa = null;
if (o.kind === 'list_session') wa = { type: 'interactive', interactive: { type: 'list', body: { text: o.body }, action: { button: 'See times', sections: [{ title: 'Open times', rows: o.rows }] } } };
else if (o.kind === 'flow_session') wa = { type: 'interactive', interactive: { type: 'flow', body: { text: o.body }, action: { name: 'flow', parameters: { flow_message_version: '3', flow_id: j.brand.booking_flow_id || $env.RESCHEDULE_FLOW_ID, flow_cta: 'Pick a new time', flow_action: 'data_exchange', flow_token: 'resched:' + j.bk.id } } } };
else if (o.kind === 'template') { const comps = [{ type: 'body', parameters: o.vars.map((t) => ({ type: 'text', text: String(t) })) }]; (o.buttons || []).forEach((p, i) => comps.push({ type: 'button', sub_type: 'quick_reply', index: String(i), parameters: [{ type: 'payload', payload: p }] })); if (o.template === 'reschedule_offer_v2') comps.push({ type: 'button', sub_type: 'flow', index: '0', parameters: [{ type: 'action', action: { flow_token: 'resched:' + j.bk.id } }] }); wa = { type: 'template', template: { name: o.template, language: { code: 'en' }, components: comps } }; }
else if (o.kind === 'text_session') wa = { type: 'text', text: { body: o.body } };
else if (o.kind === 'prebuilt') wa = o.wa; // reschedule_card (lib/wa-provider.mjs rescheduleCardPlan), sent as built
return { json: { ...j, offer: o, wa: wa ? { messaging_product: 'whatsapp', to: j.ld.phone, ...wa } : null, text: o.body || o.template || o.kind } };

const L = require('lv-automation').w10;
const j = $('Merge context').item.json;
const claimed = !!$('Claim reschedule key (idempotency)').item.json.id;
const start = j.pick.start; const end = new Date(Date.parse(start) + j.br.slot_minutes * 60000).toISOString();
const after = Date.parse(j.bk.ends_at) <= Date.now() || ['no_show', 'attended', 'rescheduled'].includes(j.bk.status);
const d = L.applyReschedule(j.bk, { start, end }, { now_ms: Date.now(), free: !!$json.free, next_slots: $json.next_slots || [], initiated_by: j.source === 'W12' ? 'broker' : 'lead', after_meeting: after, idempotency_key: 'k', seen_keys: new Set(claimed ? [] : ['k']) });
return { json: { ...j, d, new_start: start, new_end: end, rebooked_after_no_show: j.bk.status === 'no_show' } };

const L = require('lv-automation').w10;
const j = $('Decide move (w10.applyReschedule)').item.json;
const label = L.slotLabel(j.new_start);
const lead = { messaging_product: 'whatsapp', to: j.ld.phone, type: 'text', text: { body: 'Done. Your call with ' + String(j.br.contact_person).split(' ')[0] + ' is now ' + label + '.' } };
const notice = L.brokerNotice(j.d.broker_notice, j.ld);
const who = (String(j.ld.first_name || '').trim() + ' ' + (j.ld.last_name ? String(j.ld.last_name).trim().slice(0, 1) + '.' : '')).trim();
const dayOf = (iso) => new Date(Date.parse(iso) + 7200000).toISOString().slice(0, 10);
// Outside the broker's 24-h window: approved utility template broker_booking_changed (I-35a); the howzit@ email still goes as the written record.
const tpl = (oldIso, nowText, dayIso) => ({ messaging_product: 'whatsapp', to: j.br.whatsapp_number, type: 'template', template: { name: 'broker_booking_changed', language: { code: 'en' }, components: [{ type: 'body', parameters: [String(j.br.contact_person || '').split(' ')[0] || 'there', who, L.METHOD_LABEL[j.bk.method] || String(j.bk.method || 'call'), L.slotLabel(oldIso), nowText].map((t) => ({ type: 'text', text: String(t) })) }, { type: 'button', sub_type: 'url', index: '0', parameters: [{ type: 'text', text: 'calendar?day=' + dayOf(dayIso) }] }] } });
const brokerWindow = Number.isFinite(j.br.last_inbound_ms) && Date.now() - j.br.last_inbound_ms < 86400000;
return [{ json: { to: 'lead', wa: lead } }, { json: { to: 'broker', brand: j.brand, bk_id: j.bk.id, email_kind: 'moved', channel: brokerWindow ? 'whatsapp' : 'email', wa: brokerWindow ? { messaging_product: 'whatsapp', to: j.br.whatsapp_number, type: 'text', text: { body: notice } } : (j.br.whatsapp_number ? tpl(j.bk.appointment_date, label, j.new_start) : null), email: { to: j.br.email, subject: 'SortMyCover booking moved', body: notice } } }];

const L = require('lv-automation').w10;
const j = $('Decide move (w10.applyReschedule)').item.json;
// x14 (17 Oct): with no offer slots this used to return wa:null (silence); slotTakenWa now sends a 'See open times' button.
// W39 /start/move: the page shows the lost slot and re-fetches /slots (lib/w10.mjs pageOwnsSlotTaken)
return { json: { to: 'lead', wa: L.pageOwnsSlotTaken(j.source) ? null : L.slotTakenWa({ phone: j.ld.phone, offer: (j.d && j.d.offer) || [], booking: j.bk, lead: j.ld, broker: j.br, delegate: j.delegate || null }) } };

const L = require('lv-automation').w10;
const j = $('Decide cancel (w10.applyCancel)').item.json;
const notice = L.brokerNotice(j.d.broker_notice, j.ld);
const who = (String(j.ld.first_name || '').trim() + ' ' + (j.ld.last_name ? String(j.ld.last_name).trim().slice(0, 1) + '.' : '')).trim();
const dayOf = (iso) => new Date(Date.parse(iso) + 7200000).toISOString().slice(0, 10);
// Outside the broker's 24-h window: approved utility template broker_booking_changed (I-35a); the howzit@ email still goes as the written record.
const tpl = (oldIso, nowText, dayIso) => ({ messaging_product: 'whatsapp', to: j.br.whatsapp_number, type: 'template', template: { name: 'broker_booking_changed', language: { code: 'en' }, components: [{ type: 'body', parameters: [String(j.br.contact_person || '').split(' ')[0] || 'there', who, L.METHOD_LABEL[j.bk.method] || String(j.bk.method || 'call'), L.slotLabel(oldIso), nowText].map((t) => ({ type: 'text', text: String(t) })) }, { type: 'button', sub_type: 'url', index: '0', parameters: [{ type: 'text', text: 'calendar?day=' + dayOf(dayIso) }] }] } });
const brokerWindow = Number.isFinite(j.br.last_inbound_ms) && Date.now() - j.br.last_inbound_ms < 86400000;
return { json: { ...j, op: 'rebook_after_cancel', to: 'broker', bk_id: j.bk.id, email_kind: 'cancelled', channel: brokerWindow ? 'whatsapp' : 'email', wa: brokerWindow ? { messaging_product: 'whatsapp', to: j.br.whatsapp_number, type: 'text', text: { body: notice } } : (j.br.whatsapp_number ? tpl(j.bk.appointment_date, 'Cancelled', j.bk.appointment_date) : null), email: { to: j.br.email, subject: 'SortMyCover booking cancelled', body: notice } } };

const L = require('lv-automation').w10;
// I-39a: one message. delegate.body (W07's fixed lines + CANCEL_CONFIRM_Q) when present, else lines.mjs in the lead's language.
const j = $json; const m = L.cancelConfirmMessage(j.bk, j.ld, j.br, j.delegate || null);
return { json: { to: 'lead', ld: j.ld, wa: L.toWa(j.ld.phone, m) } };

const L = require('lv-automation').w10;
const j = $json;
const p = String((j.msg && (j.msg.payload || j.msg.list_id)) || '').split(':');
const method = (j.delegate && j.delegate.method) || (p[0] === 'change_method' ? p[1] : null);
const d = L.changeMethod(j.bk, j.ld, j.br, method); return { json: { ...j, method, d } };

const L = require('lv-automation').w10;
// Schedule C1A point 2 (default pending NH-42): a plain "I don't want a call" / "No thanks" stops messaging AT ONCE.
// The W13 claim (option b: nofit_criteria / no_call) is made by the hourly C1A sweep below from the message log.
const j = $json; const nc = L.applyNoCall(j.bk, j.ld);
return { json: { ...j, nc, op: 'cancel_all', booking_id: j.bk.id } };

const L = require('lv-automation').w10;
const r = $json;
const d = L.c1aDecision({ lead: { id: r.lead_id, verified_at: r.verified_at, first_message_at: r.first_message_at, opted_out_at: r.opted_out_at, conv_state: r.conv_state || {} },
  booking: { id: r.booking_id, brand_id: r.brand_id, broker_id: r.broker_id, status: r.status, cancelled_at: r.cancelled_at },
  cancelled_by: r.cancelled_by === 'broker' ? 'broker' : 'lead', rebooked: r.rebooked, rebook_offered: r.rebook_offered,
  inbound_after_cancel: r.inbound_after_cancel || [], already_claimed: r.already_claimed, now_ms: Date.now(), mode: $env.W10_C1A_MODE || L.C1A_DEFAULT_MODE });
return { json: { ...r, d } };

const L = require('lv-automation').w10;
// I-39a: change -> METHOD_CHANGED (or delegate.body); reject -> lead_lines + SAME_METHOD with the adviser's methods.
const j = $('Decide method change').item.json;
const m = L.methodMessage(j.d, j.bk, j.ld, j.br, j.delegate || null, j.method);
return { json: { to: 'lead', ld: j.ld, wa: L.toWa(j.ld.phone, m) } };

const L = require('lv-automation').w05;
const s = $('Merge context').item.json;
const t = L.graphEventTarget(s.bk, s.br, { HOWZIT_MAILBOX: $env.HOWZIT_MAILBOX, SMC_SHARED_CALENDAR_ID: $env.SMC_SHARED_CALENDAR_ID });
return { json: { ...$json, gt: { ...t, route: t.error || t.route === 'none' ? 'skip' : t.route } } };

const L = require('lv-automation').w05;
const s = $('Decide cancel (w10.applyCancel)').item.json;
const t = L.graphEventTarget(s.bk, s.br, { HOWZIT_MAILBOX: $env.HOWZIT_MAILBOX, SMC_SHARED_CALENDAR_ID: $env.SMC_SHARED_CALENDAR_ID });
return { json: { ...$json, gt: { ...t, route: t.error || t.route === 'none' ? 'skip' : t.route } } };

// lib/wa-route.cjs: "Send WhatsApp" sends through smc-whatsapp-send (WHATSAPP_PROVIDER meta | twilio). Generated: edit the
// generator / route-wa-sends.mjs config, not this node. record:true (the sub writes the communications row).
const wa = $json.wa;
const exec = (typeof $execution !== 'undefined' && $execution && $execution.id) || 'x';
const idx = (typeof $itemIndex !== 'undefined') ? $itemIndex : 0;
return { json: {
  kind: 'prebuilt', wa, to: wa && wa.to,
  record: true, caller: "W10", bypass_suppression: false,
  phone_number_id: null,
  lead_id: null, broker_id: null,
  correlation: "W10:Send WhatsApp:" + exec + ':' + idx,
} };

// ONE line to the lead; the broker never heard of a held slot, so he gets nothing. Not moved (taken in the last second) -> nothing here
// (the next held-slot pick goes through the same re-check).
const L = require('lv-automation').w10;
const j = $('Decide move (w10.applyReschedule)').first().json;
const moved = $input.all().some((i) => i.json && i.json.lead_id);
if (!moved) return [];
const by = L.slotLabel(j.d.update.verify_by);
return [{ json: { to: 'lead', wa: { messaging_product: 'whatsapp', to: j.ld.phone, type: 'text', text: { body: 'Done. We are now holding ' + L.slotLabel(j.new_start) + ' for you. Please confirm your email (the link or the 6-digit code we sent) by ' + by + ', or we will release the time.' } } } }];

// W04 reads { op: list | is_free | graph_token, broker_id, ... } (lib/w04.subcallInput). W10 used to pass its own item
// (op rebook_after_cancel / reschedule / cancel), which W04 rejected (17 Oct 2026).
const j = $('Merge context').item.json;
return { json: { op: 'list', broker_id: j.br.id, lead_id: j.ld.id, exclude_booking_id: j.bk.id } };

// W04 reads { op: list | is_free | graph_token, broker_id, ... } (lib/w04.subcallInput). W10 used to pass its own item
// (op rebook_after_cancel / reschedule / cancel), which W04 rejected (17 Oct 2026).
const j = $('Merge context').item.json;
const end = new Date(Date.parse(j.pick.start) + j.br.slot_minutes * 60000).toISOString();
return { json: { op: 'is_free', broker_id: j.br.id, lead_id: j.ld.id, exclude_booking_id: j.bk.id, start: j.pick.start, end } };

// W04 reads { op: list | is_free | graph_token, broker_id, ... } (lib/w04.subcallInput). W10 used to pass its own item
// (op rebook_after_cancel / reschedule / cancel), which W04 rejected (17 Oct 2026).
return { json: { op: 'graph_token', broker_id: $('Merge context').item.json.br.id } };

// W04 reads { op: list | is_free | graph_token, broker_id, ... } (lib/w04.subcallInput). W10 used to pass its own item
// (op rebook_after_cancel / reschedule / cancel), which W04 rejected (17 Oct 2026).
return { json: { op: 'graph_token', broker_id: $('Decide cancel (w10.applyCancel)').item.json.br.id } };

// SortMyCover brand -> smc-email-send request (Resend, SortMyCover sender); other brands -> relay null -> howzit@.
const L = require('lv-automation').w10;
return { json: { ...$json, relay: L.smcBrokerRelay($json, Date.now()) } };

const L = require('lv-automation').w10;
const j = $('Decide cancel (w10.applyCancel)').item.json;
return { json: { smc_email: L.smcClientChangeEmail(j, 'booking_cancelled', Date.now()) } };

// One email per move (this node gets the lead and the broker item); an after-meeting rebooking is a W05 booking with its own email.
const L = require('lv-automation').w10;
const d = $('Decide move (w10.applyReschedule)').first().json;
if (!d.d || d.d.action !== 'move') return [];
return [{ json: { smc_email: L.smcClientChangeEmail(d, 'booking_updated', Date.now(), { start: d.new_start, end: d.new_end }) } }];

// The lead's own "Yes, cancel" always gets an answer; before 17 Oct 2026 a second cancel got silence (W07's fallback answered).
const L = require('lv-automation').w10;
const j = $('Decide cancel (w10.applyCancel)').item.json;
return { json: { ...j, to: 'lead', wa: L.cancelDoneWa({ booking: j.bk, lead: j.ld, broker: j.br, now_ms: Date.now(), last_inbound_ms: j.last_inbound_ms, delegate: j.delegate || null }) } };

// lib/w10.mjs cancelCard: the reason list (+ the header-cancel banner image to send FIRST when WA_SESSION_BANNERS=on).
const L = require('lv-automation').w10;
const j = $json;
const c = L.cancelCard(j.bk, j.ld, { WA_SESSION_BANNERS: $env.WA_SESSION_BANNERS, WHATSAPP_PROVIDER: $env.WHATSAPP_PROVIDER });
return { json: { to: 'lead', ld: j.ld, wa: c.wa, _banner: c.banner } };

// The banner image through smc-whatsapp-send (same transport, DRY_RUN_SENDS and suppression as the list); own correlation.
const wa = $json._banner;
const exec = (typeof $execution !== 'undefined' && $execution && $execution.id) || 'x';
const idx = (typeof $itemIndex !== 'undefined') ? $itemIndex : 0;
return { json: { kind: 'prebuilt', wa, to: wa && wa.to, record: false, caller: 'W10', bypass_suppression: false, phone_number_id: null, lead_id: null, broker_id: null,
  correlation: 'W10:cancel_banner:' + exec + ':' + idx } };

const L = require('lv-automation').w10;
const j = $('Merge context').item.json;
// "Something went wrong" -> hello@ + Keep my call / Cancel it; "Another reason" -> type it + Just cancel it / Keep my call
return { json: { to: 'lead', ld: j.ld, wa: j.op === 'cancel_problem' ? L.cancelProblemWa(j.bk, j.ld) : L.cancelOtherWa(j.bk, j.ld) } };
